const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='pasada-draft-project-v1', DEVICE_STORE='pasada-draft-virtual-devices-v1';
let project=defaultProject(),storageAvailable=true,layoutMigrated=false,controllerMigrated=false,undoLayout=null;
try{const old=JSON.parse(localStorage.getItem(STORE)||'null');if(old){const migrated=migrateStudyProject(old);if(!validateProject(migrated.project).length){project=migrated.project;if(migrated.changed){localStorage.setItem(STORE+(migrated.kind==='controller'?'-before-controller-placement-1':'-before-mandaue-p33'),JSON.stringify(old));localStorage.setItem(STORE,JSON.stringify(project));layoutMigrated=migrated.kind!=='controller';controllerMigrated=migrated.kind==='controller';}}}}catch{storageAvailable=false;}
