function persist(){try{localStorage.setItem(STORE,JSON.stringify(project));}catch{storageAvailable=false;toast('This browser cannot save locally. Export your project before closing.',true);}}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',6500);}
function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function current(){return replay?replay.frames[replayIndex]:engine.c2cOnline?engine.snapshot():lastVisible;}
function events(){const f=current();return replay?(replay.events||replay.frames.flatMap(x=>x.events||[])).filter(e=>e.t<=f.t):engine.events.filter(e=>engine.c2cOnline||e.t<=lastVisible.t);}
function time(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
function status(d){const f=current().intersections.find(j=>j.id===d.intersection_id);return f?.device_health?.[d.id]||'unreported';}
function healthBadge(s){return `<span class="badge ${s==='offline'?'red':s==='suspect'?'amber':s==='unreported'?'gray':''}">${esc(s.toUpperCase())}</span>`;}
function title(eyebrow,heading,sub,right=''){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p class="subtitle">${sub}</p></div>${right}</div>`;}
