 document.querySelectorAll('button[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));
 $('#source-badge').textContent=view==='replays'?'Recorded SUMO':source()==='sumo'?'SUMO replay':'Simulation';$('#source-badge').className='badge '+(view==='replays'||source()==='sumo'?'blue':'amber');
 document.body.dataset.view=view;$('.nav-secondary').open=view==='experiments';$('#main').innerHTML=({operations,vehicles,installer,replays:replayHTML,experiments})[view]();
 if(view==='replays'){running=false;studyReplay=new StudyReplay({state:studyReplayState});studyReplay.mount();}
