 if(view==='installer'&&installerMode==='area'){areaPlanner=new AreaPlanner({project,state:areaPlannerState,onSave:plan=>{if(replay)throw Error('Imported replays are read-only.');const next=saveJunctionPlan(project,plan),errors=validateProject(next);if(errors.length)throw Error(errors[0]);project=next;persist();engine.project=clone(project);engine.beaconTracker.project=engine.project;toast('Plan saved. Choose Install devices to connect its components.');return project;},onOpenStudy:id=>{installerMode='road';selectInstallationSite(id);},onOpenDevices:id=>{deviceInstallerSiteId=id;installerMode='devices';render();window.scrollTo(0,0);},onExport:plan=>download(`${plan.id}_installation_plan.json`,plan),onError:message=>toast(message,true)});areaPlanner.mount();}
 else if(view==='installer'&&installerMode==='devices'){deviceInstaller=new DeviceInstaller({project,siteId:deviceInstallerSiteId,state:deviceInstallerState,onBack:()=>{installerMode='area';render();},onDownload:download,readOnly:!!replay});deviceInstaller.mount();}
