function drawTrend(h){if(h.length<2){$('#trend').innerHTML='<div class="chart-empty">Start the replay to collect a trend.</div>';return;}const max=Math.max(10,...h.map(x=>x.queue)),pts=h.map((x,i)=>`${15+i/(h.length-1)*245},${108-x.queue/max*83}`).join(' ');$('#trend').innerHTML=`<svg class="chart" viewBox="0 0 275 125" role="img" aria-label="Total queued vehicles over simulation time"><path d="M15 25H260 M15 65H260 M15 108H260" stroke="#e9eddf" fill="none"/><polygon points="15,108 ${pts} 260,108" fill="#dce7d133"/><polyline points="${pts}" fill="none" stroke="#769467" stroke-width="2"/><text x="16" y="16" fill="#95a58b" font-size="8">${max} veh</text></svg><div class="chart-labels"><span>${time(h[0].t)}</span><span>${time(h.at(-1).t)}</span></div>`;}
function initMap(editable=false){
 if(!window.L){$('#geo-map').innerHTML='<div class="empty">Map library could not load. The remaining workflow is available.</div>';return;}
 map=L.map('geo-map',{zoomControl:true,maxZoom:21,minZoom:3,scrollWheelZoom:true,zoomSnap:.25,zoomDelta:.5}).setView([project.intersections[0].latitude,project.intersections[0].longitude],16,{animate:false});$('#geo-map').classList.toggle('border-pick-active',!!borderPick);map.attributionControl.addAttribution('Lane geometry © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>');
 const imagery=L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxNativeZoom:19,maxZoom:21,attribution:'Imagery © Esri, Vantor, Earthstar Geographics & GIS User Community'});
 const streets=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxNativeZoom:19,maxZoom:21,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'});
 const geometry=createVectorBase(L,project);mapBases={geometry,imagery,streets};
 let tileErrors=0;imagery.on('tileerror',()=>{if(++tileErrors>=3&&map.hasLayer(imagery)&&$('#tile-warning'))$('#tile-warning').style.display='block';});imagery.on('tileload',()=>{tileErrors=0;if($('#tile-warning'))$('#tile-warning').style.display='none';});setMapBase(borderPick?'imagery':mapBaseMode);L.control.scale({imperial:false,position:'bottomleft'}).addTo(map);
 const laneLayer=L.layerGroup().addTo(map),corridorLayer=L.layerGroup();
 for(const link of project.study_area?.corridor_links||[]){L.polyline(link.path,{className:'study-corridor-line',color:'#f1c55a',weight:4,opacity:.65,dashArray:'9 7',interactive:false}).addTo(corridorLayer);const middle=pointAlong(link.path,pathLength(link.path)/2);if(!editable)L.marker(middle,{interactive:false,keyboard:false,icon:L.divIcon({className:'corridor-label',html:`<span>${esc(link.from_site)} → ${esc(link.to_site)} · ${link.reported_distance_m.toFixed(2)} m<small>reported in paper p.33</small></span>`,iconSize:[175,32],iconAnchor:[85,16]})}).addTo(corridorLayer);}

 for(const j of project.intersections){
  for(const lane of j.lanes){if(!lane.path||editable&&j.id!==installerSiteId)continue;const band=laneEnvelope(lane,lane.flow==='inbound'?65:(j.downstream_offset_m||10)+5);for(const edge of [band.left,band.right])L.polyline(edge,{className:'draft-lane-border',color:'#f3f6f7',weight:1,opacity:.55,dashArray:'8 5',interactive:false}).addTo(laneLayer);L.circleMarker(lane.path[0],{radius:2,color:'#fff',weight:1,fillOpacity:.45,interactive:false}).addTo(laneLayer);}
  if(editable){const selected=j.id===installerSiteId,tip=`<strong>${esc(j.mapped_name||j.name)}</strong><br>${selected?'Selected intersection':'Click to preview the installation'}<br>${project.devices.filter(d=>d.role==='sensor'&&d.intersection_id===j.id).length} planned pucks`;
   const area=L.circle([j.latitude,j.longitude],{radius:22,className:'installation-site-target',color:selected?'#f4c65d':'#94c8ee',weight:selected?3:2,fillColor:selected?'#f4c65d':'#3e92c3',fillOpacity:selected?.15:.1,bubblingMouseEvents:false}).addTo(map).bindTooltip(tip,{direction:'top',className:'site-hover-tooltip'});
   area.on('mouseover',()=>{if(!borderPick)area.setStyle({weight:3,fillOpacity:.3});});area.on('mouseout',()=>area.setStyle({weight:selected?3:2,fillOpacity:selected?.15:.1}));area.on('click',()=>{if(!borderPick)selectInstallationSite(j.id);});
   const decorateTarget=()=>{const target=area.getElement();if(!target)return;target.setAttribute('role','button');target.setAttribute('aria-label',`Select intersection ${j.mapped_name||j.name}`);target.setAttribute('aria-pressed',String(selected));target.setAttribute('tabindex','0');target.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(!borderPick)selectInstallationSite(j.id);}});};area.on('add',decorateTarget);decorateTarget();
   L.marker([j.latitude,j.longitude],{interactive:true,keyboard:false,icon:L.divIcon({className:'installation-site-label',html:`<button class="installation-map-label ${selected?'is-selected':''}" data-installation-site="${esc(j.id)}" aria-pressed="${selected}" title="${esc(j.mapped_name||j.name)} — click to preview"><b>${esc(j.study_number||j.id)}</b><span>${esc(j.name.replace(/^\d+ · /,''))}<small>${selected?'SELECTED · PUCK OVERLAY VISIBLE':'CLICK TO PREVIEW'}</small></span></button>`,iconSize:[190,46],iconAnchor:[-18,23]})}).addTo(map);
  }else{L.marker([j.latitude,j.longitude],{interactive:false,keyboard:false,icon:L.divIcon({className:'site-label',html:`<span class="site-label-pill">${esc(j.study_number?j.name:j.id)}<small>${esc(j.id)}</small></span>`})}).addTo(map);}
 }
 L.control.layers({'Clean geometry':geometry,'Satellite reference':imagery,'Street map':streets},{'Draft lane borders and references':laneLayer,'Paper study corridor':corridorLayer},{position:'topright',collapsed:true}).addTo(map);
 map.on('baselayerchange',e=>{const mode=Object.keys(mapBases).find(k=>mapBases[k]===e.layer);if(mode){if(!borderPick)mapBaseMode=mode;updateMapAppearance(mode);}});
 const updateZoomDetail=()=>{const element=$('#geo-map');if(!element)return;element.classList.toggle('map-detail',map.getZoom()>=19);element.classList.toggle('map-regional',map.getZoom()<15);element.dataset.zoom=map.getZoom().toFixed(2);};map.on('zoomend',updateZoomDetail);updateZoomDetail();
 map.on('geometrycoverage',e=>{if(!map.hasLayer(geometry))return;const warning=$('#tile-warning');if(warning){warning.textContent='Regional road tiles could not load. Local study detail remains available; try Satellite reference or check the connection.';warning.style.display=e.available?'none':'block';}});
 const studyCenter=L.latLngBounds(project.intersections.map(j=>[j.latitude,j.longitude])).getCenter();L.marker(studyCenter,{keyboard:false,interactive:true,icon:L.divIcon({className:'study-area-label',html:`<button data-action="fit"><b>PASADA · ${project.intersections.length} study intersections</b><span>Click to return to the study corridor ↗</span></button>`,iconSize:[230,48],iconAnchor:[115,24]})}).addTo(map);
 map.on('click',e=>{if(!borderPick)return;borderPick.points.push([e.latlng.lat,e.latlng.lng]);if(borderPick.points.length===1){L.circleMarker(borderPick.points[0],{radius:5,color:'#fff',fillColor:'#f6ce65',fillOpacity:1}).addTo(selectionLayer);$('#border-pick-instruction').textContent='Now click the opposite border of the same lane, directly across from the first point.';return;}try{const p=clone(project);alignLaneBetweenBorders(p,borderPick.deviceId,...borderPick.points);const errors=validateProject(p);if(errors.length)throw Error(errors[0]);undoLayout=clone(project);project=p;borderPick=null;persist();resetEngine();follow=true;render();toast('Puck row centred between the two picked borders. Distances remain 5 / 30 / 60 m.');}catch(err){borderPick.points=[];updateMarkers();$('#border-pick-instruction').textContent=err.message+' Try the first border again.';}});
 selectionLayer=L.layerGroup().addTo(map);beaconLayer=L.layerGroup().addTo(map);
 for(const d of project.devices){
  const initialPosition=displayedPosition(d);if(!initialPosition||editable&&(d.intersection_id!==installerSiteId||d.role==='beacon'&&!(installerDeviceChosen&&d.id===selectedD)))continue;
  if(editable&&d.role==='sensor')L.circle([d.latitude,d.longitude],{radius:PROPOSED_PUCK_DIAMETER_M/2,color:'#ffb451',weight:1,fillColor:'#ffb451',fillOpacity:1,interactive:false,className:'physical-puck-footprint'}).addTo(laneLayer);
  const marker=L.marker(initialPosition,{draggable:editable&&installerDrag,icon:deviceIcon(d),keyboard:true,title:editable?`Planning reference ${d.id}, ${d.role}; click to inspect`:`${d.id}, ${d.role}, proposed position`}).addTo(map);
  const lane=project.intersections.find(j=>j.id===d.intersection_id)?.lanes.find(l=>l.id===d.lane_id);marker.bindTooltip(`${editable?'<span class="tooltip-overline">PROVISIONAL PLANNING REFERENCE</span>':''}<strong>${esc(d.id)}</strong>${d.role==='sensor'?`<br>${esc(lane?.road_name||d.approach)} · lane ${lane?.lane_number||1}<br>${d.placement==='upstream'?`${d.offset_m} m upstream`:`Downstream counter · ${d.offset_m} m after exit reference`}`:''}${editable?'<br><span class="tooltip-note">'+esc(planningIdentity(d).status)+'</span>':''}`,{direction:'top',offset:[0,-7],className:editable?'planning-puck-tooltip':''});marker.on('click',()=>{selectedD=d.id;selectedJ=d.intersection_id;if(editable)installerDeviceChosen=true;updateMarkers();if(view==='operations')updateOperations();else renderInstallerSelection();});
  if(editable)marker.on('dragend',()=>{const pos=marker.getLatLng();undoLayout=clone(project);movePuckAndLane(project,d.id,pos.lat,pos.lng);persist();resetEngine();render();renderInstallerSelection();toast(d.role==='sensor'?'Lane moved together; the required detector offsets are preserved.':'Controller position updated.');});
  markers.set(d.id,marker);
 }
 if(editable&&installerSiteId)fitInstallationSite();else fitMap();if(follow){const d=project.devices.find(d=>d.id===selectedD);if(d){const j=project.intersections.find(j=>j.id===d.intersection_id);map.setView(hasDevicePosition(d)?[d.latitude,d.longitude]:[j.latitude,j.longitude],19,{animate:false});}follow=false;}
 setTimeout(()=>map?.invalidateSize(),80);
}
function updateMapAppearance(mode){const el=$('#geo-map');el?.classList.toggle('geometry-map',mode==='geometry');if(el)el.dataset.mapBase=mode;for(const button of document.querySelectorAll('.map-base-switch button'))button.setAttribute('aria-pressed',String(button.dataset.action==='map-'+mode));const caption=$('.map-base-caption');if(caption)caption.textContent=mode==='geometry'?'Continuous road map · local building footprints':mode==='imagery'?'Satellite reference imagery · not a live feed':'OpenStreetMap reference tiles';const note=$('.geometry-map-caption');if(note)note.hidden=mode!=='geometry';if($('#tile-warning'))$('#tile-warning').style.display='none';}
function setMapBase(mode){if(!map||!mapBases?.[mode])return;for(const [key,layer] of Object.entries(mapBases))if(key!==mode&&map.hasLayer(layer))map.removeLayer(layer);if(!map.hasLayer(mapBases[mode]))mapBases[mode].addTo(map);if(!borderPick)mapBaseMode=mode;updateMapAppearance(mode);}
function fitMap(){if(map)map.fitBounds(L.latLngBounds([...project.intersections.map(j=>[j.latitude,j.longitude]),...project.devices.filter(hasDevicePosition).map(d=>[d.latitude,d.longitude])]).pad(.12),{maxZoom:18,padding:[25,25]});}
function deviceIcon(d){const st=status(d),shape=d.role==='controller'?'controller-triangle':d.role==='beacon'?'beacon-diamond':d.placement==='downstream'?'sensor-dot counter-dot':'sensor-dot';return L.divIcon({className:`device-pin ${st} ${d.id===selectedD&&(view!=='installer'||installerDeviceChosen)?'selected':''} ${d.role==='beacon'&&(current().beacon_tracks||[]).find(t=>t.beacon_id===d.id)?.status==='stale'?'stale-beacon':''}`,html:`<span class="${shape}" ${st==='unreported'?'style="filter:grayscale(1)"':''}></span>`,iconSize:[24,24],iconAnchor:[12,12]});}
function updateMarkers(){if(!map)return;for(const d of project.devices){let m=markers.get(d.id);if(!m&&d.role==='beacon'&&view==='operations'&&displayedPosition(d)){const v=fleetRecords(project).find(v=>v.beacon_id===d.id);m=L.marker(displayedPosition(d),{icon:deviceIcon(d),title:`${v?.call_sign||d.id} · emergency beacon`}).bindTooltip(`${esc(v?.call_sign||d.id)}<br>${esc(d.id)}`).addTo(map);m.on('click',()=>{selectedD=d.id;updateDeviceDetail();});markers.set(d.id,m);}if(m){m.setIcon(deviceIcon(d));const position=displayedPosition(d);if(position)m.setLatLng(position);}}if(beaconLayer){beaconLayer.clearLayers();for(const track of view==='installer'?[]:current().beacon_tracks||[]){const trail=replay?replay.frames.filter(f=>f.t<=current().t).slice(-12).flatMap(f=>(f.beacon_tracks||[]).filter(t=>t.beacon_id===track.beacon_id).map(t=>[t.latitude,t.longitude])):engine.beaconPackets.filter(p=>p.beacon_id===track.beacon_id&&p.timestamp_s<=current().t).slice(-12).map(p=>[p.latitude,p.longitude]);if(trail.length>1)L.polyline(trail,{color:track.status==='stale'?'#929daa':'#8ebaff',weight:3,opacity:.8,interactive:false}).addTo(beaconLayer);}}if(selectionLayer){selectionLayer.clearLayers();const d=project.devices.find(d=>d.id===selectedD),j=d&&project.intersections.find(j=>j.id===d.intersection_id);if(d&&j&&d.role==='sensor'&&(view!=='installer'||installerDeviceChosen&&installerSiteId===j.id)){const lane=j.lanes.find(l=>l.id===d.lane_id);if(lane?.path){const band=laneEnvelope(lane,lane.flow==='inbound'?65:(j.downstream_offset_m||10)+8),color=lane.flow==='inbound'?'#ffca7c':'#80e7e8';L.polygon([...band.left,...[...band.right].reverse()],{color,weight:0,fillOpacity:.14,interactive:false}).addTo(selectionLayer);for(const edge of [band.left,band.right])L.polyline(edge,{className:'selected-lane-border',color:'#fff',weight:2,opacity:1,dashArray:'9 6',interactive:false}).addTo(selectionLayer);const cross=laneCrossSection(lane,d.offset_m);L.polyline([cross.left,cross.right],{color,weight:1,opacity:.8,interactive:false}).addTo(selectionLayer);L.circleMarker(lane.path[0],{radius:4,color:'#fff',weight:2,fillColor:'#234866',fillOpacity:1,interactive:false}).bindTooltip('Signal / exit reference · 0 m').addTo(selectionLayer);for(const sibling of project.devices.filter(x=>x.lane_id===lane.id&&x.intersection_id===j.id&&x.role==='sensor'))L.marker([sibling.latitude,sibling.longitude],{interactive:false,keyboard:false,icon:L.divIcon({className:'offset-label',html:`<span>${sibling.placement==='upstream'?sibling.offset_m+' m':'OUT'}</span>`,iconSize:[35,16],iconAnchor:[-8,9]})}).addTo(selectionLayer);}}}}
function updateDeviceDetail(){const el=$('#device-detail');if(!el)return;const d=project.devices.find(d=>d.id===selectedD)||project.devices[0],j=project.intersections.find(j=>j.id===d.intersection_id),lane=j.lanes.find(l=>l.id===d.lane_id),count=current().intersections.find(x=>x.id===j.id)?.device_counts?.[d.id];el.innerHTML=`<div class="tool-heading"><strong class="mono">${esc(d.id)}</strong>${healthBadge(status(d))}</div><dl class="detail-list"><dt>Role / site</dt><dd>${esc(d.role)} / ${esc(d.intersection_id)}</dd><dt>Coordinates</dt><dd>${d.role==='beacon'?(displayedPosition(d)?displayedPosition(d).map(n=>n.toFixed(7)).join(', ')+' · position telemetry':'Mobile · awaiting position telemetry'):hasDevicePosition(d)?`${d.latitude.toFixed(7)}, ${d.longitude.toFixed(7)}`:'Cabinet location not yet surveyed'}</dd><dt>Placement</dt><dd>${d.role==='sensor'?`${esc(d.approach)} · ${esc(d.placement)} · ${d.offset_m} m nominal`:d.role==='controller'?'Roadside cabinet / approved enclosure. Junction reference is not a cabinet position.':'Vehicle-mounted beacon; position comes from its current telemetry.'}</dd>${lane?.path?`<dt>Road / lane</dt><dd>${esc(lane.road_name)} · ${lane.flow} ${lane.lane_number}</dd><dt>Alignment</dt><dd>Lane midpoint · ${(lane.lane_width_m||3).toFixed(2)} m draft width · ${((lane.lane_width_m||3)/2).toFixed(2)} m to each border</dd><dt>Reference</dt><dd>${lane.path[0][0].toFixed(7)}, ${lane.path[0][1].toFixed(7)}</dd><dt>Border reference</dt><dd>${lane.border_alignment?'Two operator-picked imagery edges; unsurveyed':'Assumed lane width; imagery alignment still provisional'}</dd><dt>Passage count</dt><dd>${Number.isFinite(count)?`${count} · synthetic tally`:d.offset_m===5||d.offset_m===30?'Queue detector; excluded from inflow total':'Unreported'}</dd>`:''}${d.role==='controller'?'<dt>Hardware</dt><dd>ESP32-C3 Super Mini · RTC · LoRa</dd><dt>Timing authority</dt><dd>One intersection coordinator; all signal movements share its phase logic.</dd>':''}<dt>Commissioning</dt><dd>${esc(d.commissioning?.state||'planned')} · simulated transport</dd></dl><div class="row-actions">${lane?.path?'<button class="button small" data-action="focus-lane">Focus lane</button><button class="button small" data-action="border-align">Centre between lane borders</button>':''}<button class="button small" data-action="edit-selected">Edit installation</button><button class="button small danger" data-action="fault" ${replay?'disabled':''}>${engine.failed.has(d.id)?'Restore heartbeat':'Stop heartbeat'}</button></div><div class="device-selection"><label class="hint">Scenario actions at ${esc(j.id)}</label><div class="row-actions spacer"></div><div class="row-actions"><button class="button small" data-action="emergency" ${replay?'disabled':''}>Track ambulance approach</button><button class="button small" data-action="pedestrian" ${replay?'disabled':''}>Pedestrian request</button><button class="button small" data-action="c2c" ${replay?'disabled':''}>${engine.c2cOnline?'Disconnect C2C':'Reconnect C2C'}</button></div></div>${replay?'<p class="section-note">Imported replay is read-only. No live hardware health is inferred from traffic data.</p>':''}`;}
function beaconPanelHTML(){return `<section class="panel subsection beacon-panel"><div class="panel-head"><div><span class="eyebrow">EMERGENCY VEHICLE / POSITION BEACONS</span><h2>Track the approach. Request local priority.</h2></div><span class="badge blue">1 Hz SYNTHETIC GPS STREAM</span></div><div class="panel-body"><div class="beacon-controls"><label>Demonstration intersection<select id="beacon-target" ${replay?'disabled':''}>${project.intersections.map(j=>`<option value="${esc(j.id)}" ${j.id===selectedJ?'selected':''}>${esc(j.name)}</option>`).join('')}</select></label><button class="button dark" data-action="beacon-start" ${replay?'disabled':''}>Simulate ambulance approach</button><button class="button" data-action="beacon-pause" id="beacon-pause" ${replay||!engine.beaconDemo?'disabled':''}>Pause packets</button><button class="button" data-action="beacon-export" ${replay?'disabled':''}>Export beacon packets</button></div><div id="beacon-status" class="beacon-status"></div><p class="section-note">Unique beacon ID + session + sequence + timestamp → consecutive GPS fixes → derived heading/speed → incoming approach → local coordinator. The demo uses a simulated enrolled identity. Live authentication, ESP-NOW and LoRa are not implemented. GPS uncertainty can prevent individual-lane identification.</p></div></section>`;}
function updateBeaconPanel(){const box=$('#beacon-status');if(!box)return;const tracks=current().beacon_tracks||[];const compact=$('#beacon-map-status');if(compact){const t=tracks[0];compact.innerHTML=t?`<span class="eyebrow">SYNTHETIC EMERGENCY BEACON</span><strong>${esc(t.beacon_id)} · ${esc(t.status)}</strong><div>${Number.isFinite(t.speed_mps)?(t.speed_mps*3.6).toFixed(1)+' km/h':'Speed unresolved'} · ${Number.isFinite(t.heading_deg)?t.heading_deg.toFixed(0)+'°':'Heading pending'}</div><div>${t.match?esc(t.match.controller_id)+' · '+esc(t.match.approach)+' approach':'Awaiting incoming-road match'}</div><small>${t.match?.lane_id?'Lane: geometric candidate':'Individual lane may be unresolved'} · fix age ${t.age_s.toFixed(0)} s</small>${!replay&&engine.beaconDemo&&!engine.beaconDemo.finished?`<button class="button small" data-action="beacon-pause">${engine.beaconDemo.paused?'Resume beacons':'Pause beacons'}</button>`:''}`:'<span class="hint">Use Ambulance demo to inspect a moving beacon.</span>';}const pause=$('#beacon-pause');if(pause){pause.disabled=!!replay||!engine.beaconDemo||engine.beaconDemo.finished;pause.textContent=engine.beaconDemo?.paused?'Resume packets':'Pause packets';}const select=$('#beacon-target');if(select&&document.activeElement!==select)select.value=selectedJ;if(!tracks.length){box.innerHTML='<div class="empty">Start an approach to inspect the moving beacon, inferred heading, speed, target coordinator and freshness lease.</div>';return;}box.innerHTML=tracks.map(t=>{const m=t.match,j=project.intersections.find(j=>j.id===m?.intersection_id),cabinet=project.devices.find(d=>d.id===j?.controller_device_id),request=t.local_request;return `<div class="beacon-track"><div class="tool-heading"><strong>${esc(t.beacon_id)} <span class="hint">/ ${esc(t.vehicle_id||'vehicle')}</span></strong><span class="badge ${t.priority_eligible?'blue':t.status==='stale'?'amber':'gray'}">${esc(t.status.toUpperCase())}</span></div><div class="beacon-metrics"><div>Derived speed<strong>${Number.isFinite(t.speed_mps)?(t.speed_mps*3.6).toFixed(1)+' km/h':'—'}</strong></div><div>Derived heading<strong>${Number.isFinite(t.heading_deg)?t.heading_deg.toFixed(1)+'°':'—'}</strong></div><div>Position age<strong>${t.age_s.toFixed(0)} s</strong></div><div>ETA to reference<strong>${Number.isFinite(t.eta_s)?t.eta_s.toFixed(1)+' s':'—'}</strong></div></div><dl class="detail-list"><dt>Received fix</dt><dd>${t.latitude.toFixed(7)}, ${t.longitude.toFixed(7)} · accuracy input ±${t.position_accuracy_m} m (synthetic)</dd><dt>Consecutive fixes</dt><dd>Sequence ${t.sequence} · ${Number.isFinite(t.motion_window_s)?t.motion_window_s.toFixed(1)+' s motion window':'waiting for movement above uncertainty'}</dd><dt>Approach / lane</dt><dd>${m?`${esc(m.road_name)} · ${m.lane_id?esc(m.lane_id)+' · geometric candidate': 'individual lane unresolved'}`:'No current incoming-road match'}</dd><dt>Destination</dt><dd>${m?`${esc(m.controller_id)} / ${esc(j?.name)}${!hasDevicePosition(cabinet)?' · cabinet location unassigned':''}`:'No controller request'}</dd><dt>Priority request</dt><dd>${t.priority_eligible&&request?`${esc(m.axis)} group · bounded lease, complete clearance required${!replay&&request?.until?'; remaining '+Math.max(0,request.until-current().t).toFixed(0)+' s':''}`:'Released / not eligible'}</dd><dt>Identity / hardware</dt><dd>${replay?'Recorded replay; no live verification':'Simulated enrolled identity only'} · no physical signal output</dd></dl></div>`;}).join('');}
function controllerLocationsHTML(){const ds=project.devices.filter(d=>d.role==='controller');return `<section class="panel controller-panel subsection"><div class="panel-head"><div><span class="eyebrow">INTERSECTION HARDWARE / PLACEMENT</span><h2>${ds.length} local coordinators · one per intersection</h2></div><span class="badge blue">ESP32-C3 + RTC + LoRa</span></div><div class="table-wrap"><table><thead><tr><th>COORDINATOR</th><th>STUDY INTERSECTION</th><th>ROADSIDE CABINET LOCATION</th><th></th></tr></thead><tbody>${ds.map(d=>{const j=project.intersections.find(j=>j.id===d.intersection_id);return `<tr><td class="mono">${esc(d.id)}</td><td>${esc(j.name)}</td><td>${hasDevicePosition(d)?`${d.latitude.toFixed(7)}, ${d.longitude.toFixed(7)}<br><span class="hint">${esc(d.location_status||'provisional')}</span>`:'<span class="badge amber">NOT YET SURVEYED</span>'}</td><td><button class="button small" data-controller="${esc(d.id)}">${hasDevicePosition(d)?'Edit cabinet position':'Set cabinet position'}</button></td></tr>`;}).join('')}</tbody></table></div><div class="panel-body controller-explanation"><p><strong>The junction reference and cabinet position are different.</strong> One PASADA coordinator serves all movements at its intersection, through an interface with the existing signal controller that still needs technical confirmation. Per-pole receiver or I/O modules would be a separate design choice, not four independent timing authorities.</p><div class="hardware-chain"><span><b>${ds.length} intersection coordinators</b>ESP32-C3 · RTC · ESP-NOW · LoRa</span><i>LoRa telemetry →</i><span><b>1 proposed C2C receiver / gateway</b>Monitoring and logs · separate from local timing</span></div><p class="section-note">The RTC retains a time reference; it does not automatically synchronize separate devices. Pucks follow their local coordinator's time. Clock source, resynchronization, drift limits and backup behavior remain to be specified; timeouts use elapsed monotonic time. No radio or RTC hardware is connected in this browser demo.</p></div></section>`;}
function selectInstallationSite(id){const j=project.intersections.find(j=>j.id===id);if(!j)return;installerSiteId=id;selectedJ=id;selectedD=j.controller_device_id;installerDeviceChosen=false;installerDrag=false;borderPick=null;render();}
function fitInstallationSite(){if(map&&installerSiteId)map.fitBounds(L.latLngBounds(installationBoundsPoints(project,installerSiteId)).pad(.04),{maxZoom:20,padding:[18,18],animate:false});}
function installationSummary(){const j=project.intersections.find(j=>j.id===installerSiteId);if(!j)return `<div class="installation-empty"><div class="pick-symbol">⌖</div><div class="eyebrow">START ON THE MAP</div><h3>Choose a study intersection</h3><p>Hover a crossing to see its name and a hand cursor. Left-click the highlighted area or its label to reveal the proposed puck positions.</p><p class="section-note">Only the three configured study intersections are selectable. These locations come from the study, rather than automatic detection of every road crossing.</p></div>`;
 const ds=installationDevices(project,j.id),incoming=j.lanes.filter(l=>l.flow==='inbound').length,outgoing=j.lanes.filter(l=>l.flow==='outbound').length;
 return `<div class="installation-summary"><span class="badge blue">INTERSECTION SELECTED</span><h3>${esc(j.mapped_name||j.name)}</h3><p class="mono">${esc(j.id)} · ${j.latitude.toFixed(7)}, ${j.longitude.toFixed(7)}</p><div class="installation-counts"><div><strong>${ds.filter(d=>d.role==='sensor').length}</strong><span>Planned pucks</span></div><div><strong>${incoming} / ${outgoing}</strong><span>Incoming / outgoing lanes</span></div></div><p>Hover a puck for its planning reference. Click a puck to inspect its lane, coordinates and configuration.</p><p class="section-note">5 / 30 / 60 m upstream per incoming lane. One downstream counter per outgoing lane. White dashed lines are lane borders.</p><a class="button" href="${googleMapsUrl(j)}" target="_blank" rel="noopener">Open this crossing in Google Maps ↗</a><div class="identity-note"><strong>Identifiers are still a draft.</strong><p>The labels currently identify planned positions. A permanent hardware UID has not been assigned to these demo pucks.</p><button class="subtle-link" data-action="identity-notes">View the proposed identity approach ↗</button></div><button class="button small" data-controller="${esc(j.controller_device_id)}">Configure roadside coordinator</button></div>`;}
function installer(){if(installerMode==='devices')return deviceInstallerHTML();if(installerMode==='area')return areaPlannerHTML();if(installerMode==='beacon')return beaconInstaller();const chosen=project.intersections.find(j=>j.id===installerSiteId);return title('INSTALLATION / INTERSECTION PICKER','Choose a crossing. See the installation.','Hover an intersection, left-click to select it, then inspect the proposed pucks on the road.',`<button class="button" data-action="edit-sites">Study settings</button>`)+`
 <div class="installation-mode-switch" role="group" aria-label="Installation type"><button class="button" data-action="install-area-mode">Area planner</button><button class="button dark" data-action="install-road-mode" aria-pressed="true">Configured sites</button><button class="button" data-action="install-beacon-mode">Vehicle beacons</button><span>Set up road equipment here. Register vehicles in Emergency fleet first.</span></div><div class="steps installation-steps"><div class="step ${!chosen?'active':''}"><b>01</b> Choose intersection</div><div class="step ${chosen&&!installerDeviceChosen?'active':''}"><b>02</b> Preview pucks</div><div class="step ${installerDeviceChosen?'active':''}"><b>03</b> Configure device</div></div>
 <div class="installation-site-choices" aria-label="Study intersections">${project.intersections.map(j=>`<button class="installation-site-choice ${j.id===installerSiteId?'is-selected':''}" data-installation-site="${esc(j.id)}" aria-pressed="${j.id===installerSiteId}" title="${esc(j.mapped_name||j.name)}"><b>${esc(j.study_number||j.id)}</b><span>${esc(j.name.replace(/^\d+ · /,''))}</span></button>`).join('')}</div>
 <div class="installer-grid installer-picker"><section class="panel installation-map-panel"><div class="panel-head wrap"><div><span class="eyebrow">GEOGRAPHIC INSTALLATION PREVIEW</span><h2>${chosen?'Installation preview · '+esc(chosen.name):'Hover or click a study intersection'}</h2></div><div class="row-actions">${chosen?`<a class="button small" href="${googleMapsUrl(chosen)}" target="_blank" rel="noopener">Google Maps ↗</a>`:''}<button class="button small" data-action="installer-all">All intersections</button>${chosen?'<button class="button small" data-action="installer-fit">Fit installation</button><button class="button small" data-action="installer-drag">'+(installerDrag?'Disable dragging':'Enable dragging')+'</button>':''}</div></div><div class="geometry-view-bar"><div class="map-base-switch" role="group" aria-label="Map appearance"><button data-action="map-geometry" aria-pressed="true">Clean geometry</button><button data-action="map-imagery" aria-pressed="false">Satellite reference</button></div><span>SAME GEOGRAPHIC EQUIPMENT COORDINATES</span></div>${borderPick?'<div class="border-pick-banner"><strong>Centre this row between two lane borders</strong><p id="border-pick-instruction">Click one border beside the selected puck, then the opposite border at the same station. Use the satellite markings, not the draft overlay.</p><button class="button small" data-action="border-cancel">Cancel border alignment</button></div>':''}<div class="map-wrap"><div class="geo-map" id="geo-map" aria-label="Installation map: select a study intersection"></div><div class="map-overlay"><strong>${chosen?'SELECTED INTERSECTION · '+esc(chosen.id):'HOVER A CROSSING → LEFT-CLICK TO SELECT'}</strong>${chosen?'Hover a puck for its provisional ID; click to inspect.<br>White dashed lines = lane borders; pucks = midpoint.':'Only the three study crossings are selectable.<br>Puck overlays appear after you choose a crossing.'}</div><div id="tile-warning" class="map-warning">Satellite imagery unavailable. Choose Clean geometry in Layers.</div></div><div class="map-legend"><span class="legend-item"><i class="legend-dot"></i> Upstream puck</span><span class="legend-item"><i class="legend-dot counter-legend"></i> Downstream counter</span><span class="legend-item"><i class="lane-border-key"></i> Draft lane borders</span><span class="legend-item">Metre-based geometry · scale bar follows zoom</span></div><div class="installation-scale-note">Detector spacing and lane widths follow geographic coordinates. Click targets are enlarged for selection; the Rev B puck body is proposed at Ø123 mm. Placement and lane widths still need field verification.</div></section>
 <section class="panel installation-device-panel"><div class="panel-head"><div><span class="eyebrow">${installerDeviceChosen?'DEVICE CONFIGURATOR':'INSTALLATION PREVIEW'}</span><h2>${installerDeviceChosen?'Inspect and configure':'Your selected intersection'}</h2></div></div><div id="installer-selection" class="panel-body"></div></section></div>
 <section class="panel subsection installation-batch"><div class="panel-head"><h2>${chosen?'Selected intersection batch · '+installationDevices(project,chosen.id).length+' devices':'Select an intersection to view its device batch'}</h2>${chosen?'<button class="button small" data-action="add-puck">+ Add lane</button>':''}</div><div id="device-table" class="device-table"></div></section>
 <details class="handoff-detail subsection"><summary>Lane inventory and roadside cabinet registry</summary><div class="handoff-detail-content">${coverageTableHTML()}${controllerLocationsHTML()}</div></details>
 <details class="handoff-detail subsection"><summary>Installation settings, timing and exports</summary><div class="panel-body"><div class="row-actions"><button class="button" data-action="lane-layout">Lane layout</button><button class="button" data-action="timing-profiles">Timing profiles</button><button class="button" data-action="export-project">Export installation project</button></div><form id="project-form" class="subsection"><div class="split"><div><div class="field"><label for="project-name">Project name</label><input id="project-name" name="name" value="${esc(project.project.name)}" required maxlength="120"></div><div class="field"><label for="channel">ESP-NOW channel</label><input id="channel" name="channel" type="number" value="${project.communications.esp_now_channel}" min="1" max="11" required></div></div><div><div class="field"><label for="peer-budget">Encrypted peer budget per controller</label><input id="peer-budget" name="peer" type="number" value="${project.communications.encrypted_peer_budget}" min="1" max="17" required><small>Receiver topology remains a deployment constraint.</small></div><p class="section-note">The public export contains no secret keys. Radio hardware, synchronization and the signal-cabinet interface are not connected in this demo.</p></div></div><button class="button dark" type="submit">Save installation settings</button>${radioCapacityHTML()}</form></div></details>`;}
function renderInstallerTable(){const box=$('#device-table');if(!box)return;const devices=installationDevices(project,installerSiteId);box.innerHTML=devices.length?`<table><thead><tr><th>PLANNING REFERENCE · UID NOT FINAL</th><th>ROLE / POSITION</th><th>SITE</th><th>COMMISSIONING</th></tr></thead><tbody>${devices.map(d=>`<tr data-device="${esc(d.id)}" class="${installerDeviceChosen&&d.id===selectedD?'selected':''}" tabindex="0"><td>${esc(d.id)}</td><td>${d.role==='sensor'?`${esc(d.lane_id)}<br><span class="hint">${d.placement==='upstream'?`${d.offset_m} m upstream`:'Downstream counter'}</span>`:esc(d.role)}</td><td>${esc(d.intersection_id)}</td><td><span class="badge ${d.commissioning?.state==='simulated_verified'?'':'gray'}">${d.commissioning?.state==='simulated_verified'?'SIM VERIFIED':'PLANNED'}</span>${d.role==='controller'&&!hasDevicePosition(d)?'<br><span class="hint">CABINET UNLOCATED</span>':''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Choose one of the three crossings on the map to reveal its planned devices.</div>';}
function identityDialog(){$('#dialog-content').innerHTML=`<h2>Puck identity · proposed approach</h2><div class="notice blue">The current labels are unique planning references in this project. They are not a finalized hardware UID scheme.</div><ol class="identity-proposal"><li><strong>Permanent hardware UID</strong><p>An immutable identifier assigned during enrollment. It stays with the physical puck when that puck is moved or replaced. No hardware UID is assigned by this simulation.</p></li><li><strong>Installation position reference</strong><p>A readable label for the assigned site, approach, lane and detector station. Example format for discussion: <span class="mono">MD01-N-L02-U030</span>. This example has not been adopted.</p></li><li><strong>Commissioning record</strong><p>Bind the hardware UID to the planning reference, controller, lane, coordinates, firmware and installation revision. Replacing a puck changes the hardware binding while preserving the position history.</p></li></ol><p class="section-note">An identifier is not proof of authorization. Device enrollment, authentication and radio credentials are separate work. Existing project references are retained so exports and replays remain compatible.</p><a class="button" href="./downloads/DEVICE_IDENTITY.md" download>Download identity proposal</a>`;$('#dialog').showModal();}
function laneCenterInset(lane){return `<div class="lane-center-inset"><svg viewBox="0 0 300 112" role="img" aria-label="Puck halfway between two lane borders"><rect x="28" y="20" width="244" height="72" rx="5" fill="#20374b"/><path d="M30 25H270M30 87H270" stroke="#fff" stroke-width="2" stroke-dasharray="12 7"/><path d="M153 27V85" stroke="#8ea8bb" stroke-width="1"/><path d="M124 40Q124 34 130 34H176Q182 34 182 40V72Q182 78 176 78H130Q124 78 124 72Z" fill="#dce6ec" fill-opacity=".15" stroke="#9eb5c5"/><circle cx="153" cy="56" r="5" fill="#ffb451" stroke="#fff" stroke-width="1.5"/><text x="183" y="48" fill="#dce8f0" font-size="10">${((lane.lane_width_m||3)/2).toFixed(2)} m</text><text x="183" y="74" fill="#dce8f0" font-size="10">${((lane.lane_width_m||3)/2).toFixed(2)} m</text><text x="32" y="13" fill="#506b80" font-size="9">BORDER</text><text x="32" y="107" fill="#506b80" font-size="9">BORDER</text></svg><p>Each puck is at the midpoint of the two borders, beneath the expected vehicle centre. Diagram is schematic; the width is provisional.</p></div>`;}
function renderInstallerSelection(){
 if(installerMode==='area')return;
 if(installerMode==='beacon'){if(view==='installer')$('#main').innerHTML=beaconInstaller();return;}
 const el=$('#installer-selection');if(!el)return;if(!installerSiteId||!installerDeviceChosen){el.innerHTML=installationSummary();renderInstallerTable();updateMarkers();return;}const d=project.devices.find(d=>d.id===selectedD)||project.devices[0],j=project.intersections.find(j=>j.id===d.intersection_id),lane=j.lanes.find(l=>l.id===d.lane_id);
 el.innerHTML=`<div class="identity-note compact"><strong>Planning reference · ${esc(d.id)}</strong><p>${esc(planningIdentity(d).status)}. The final UID structure is not approved.</p><button class="subtle-link" data-action="identity-notes">Identity design notes ↗</button></div><div class="notice blue"><strong>Virtual USB device.</strong> This draft verifies a browser-persisted record. No board or radio is connected.</div>${d.role==='controller'?`<div class="notice ${hasDevicePosition(d)?'blue':''}"><strong>Intersection coordinator · ${esc(j.id)}</strong><br>ESP32-C3 Super Mini + external RTC + LoRa. ${hasDevicePosition(d)?'Proposed cabinet coordinates supplied; field verification is still required.':'Cabinet whereabouts unknown. Enter the roadside cabinet coordinates before virtual installation.'}<br>Junction reference only: ${j.latitude.toFixed(7)}, ${j.longitude.toFixed(7)}.</div>`:''}<form id="device-form"><div class="field"><label for="device-id">Planned device</label><select id="device-id" name="device">${installationDevices(project,installerSiteId).map(x=>`<option value="${esc(x.id)}" ${d.id===x.id?'selected':''}>${esc(x.id)} / ${esc(x.role)}</option>`).join('')}</select></div>${lane?.path?`<dl class="detail-list"><dt>Road / lane</dt><dd>${esc(lane.road_name)} · ${lane.lane_number} · ${esc(lane.flow)}</dd><dt>Detector</dt><dd>${d.placement==='upstream'?`${d.offset_m} m upstream of signal reference`:`One downstream counter · ${d.offset_m} m after exit reference`}</dd></dl>${laneCenterInset(lane)}<div class="row-actions"><button type="button" class="button small" data-action="focus-lane">Focus lane</button><button type="button" class="button small dark" data-action="border-align">Centre between lane borders</button><button type="button" class="button small" data-action="lane-layout">Edit lane / signal reference ↗</button></div><div class="spacer"></div>`:''}<div class="two-fields"><div class="field"><label for="device-lat">${d.role==='controller'?'Cabinet latitude':'Puck / device latitude'}</label><input id="device-lat" name="latitude" type="number" step="any" value="${d.latitude??''}" min="-90" max="90" required></div><div class="field"><label for="device-lon">${d.role==='controller'?'Cabinet longitude':'Puck / device longitude'}</label><input id="device-lon" name="longitude" type="number" step="any" value="${d.longitude??''}" min="-180" max="180" required></div></div>${lane?.path?'<p class="hint">Changing this puck coordinate moves its lane reference and companion pucks together, preserving every required offset.</p>':''}<button class="button small" type="submit">Save device placement</button></form><div class="spacer"></div><div class="row-actions"><button class="button dark" data-action="commission" ${commissionBusy||!hasDevicePosition(d)?'disabled':''}>${commissionBusy?'Verifying…':'Install on virtual device'}</button><button class="button" data-action="device-json">Device JSON</button>${d.role==='controller'&&hasDevicePosition(d)?'<button class="button" data-action="unlocate-controller">Clear cabinet position</button>':''}</div><div class="progress-track"><i style="width:${commissionPercent}%"></i></div><div class="commission-log" aria-live="polite">${esc(commissionLog||'Ready. Select a located device for simulated installation.\nTransport: browser virtual device')}</div><p class="section-note">The public export retains lane paths, signal references, detector offsets and counter identities.</p>`;
 renderInstallerTable();updateMarkers();
}

async function digest(s){if(globalThis.crypto?.subtle)return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))].map(b=>b.toString(16).padStart(2,'0')).join('');let h=2166136261;for(const byte of new TextEncoder().encode(s))h=Math.imul(h^byte,16777619)>>>0;return 'fnv1a-'+h.toString(16).padStart(8,'0');}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function commission(){if(commissionBusy)return;if(replay){toast('Imported replays are read-only.',true);return;}const id=selectedD,config=deviceConfiguration(project,id),errors=validateProject(project);if(!config.installation_ready){toast(config.role==='beacon'?'Register this beacon to a vehicle before setup.':'Assign the cabinet coordinates before installing this device.',true);return;}if(errors.length){toast(errors.join(' '),true);return;}commissionBusy=true;commissionLog='';commissionPercent=0;const log=async(text,p)=>{commissionLog+=text+'\n';commissionPercent=p;if(view==='installer')renderInstallerSelection();await delay(320);};try{await log(`[VIRTUAL USB] Connected ${id}`,15);const raw=JSON.stringify(config),hash=await digest(raw);await log(`[PROFILE] ${config.role} / ${config.intersection_id} / v${VERSION}`,30);let records=JSON.parse(localStorage.getItem(DEVICE_STORE)||'{}');records[id]={config:JSON.parse(raw),sha256:hash};localStorage.setItem(DEVICE_STORE,JSON.stringify(records));await log('[PERSIST] Device configuration written to virtual flash',55);records=JSON.parse(localStorage.getItem(DEVICE_STORE));if(JSON.stringify(records[id].config)!==raw||await digest(JSON.stringify(records[id].config))!==hash)throw Error('Virtual readback hash mismatch.');await log(`[READBACK] Exact JSON and ${hash.startsWith('fnv1a-')?'non-cryptographic FNV-1a':'SHA-256'} fingerprint match`,75);await log('[REBOOT] Virtual record reloaded; identity retained',90);project.devices.find(d=>d.id===id).commissioning={state:'simulated_verified',transport:'simulated',verified_at:new Date().toISOString(),configuration_fingerprint:hash,fingerprint_algorithm:hash.startsWith('fnv1a-')?'fnv1a-non-cryptographic':'sha256'};persist();await log('[COMPLETE] SIMULATED verification. No hardware claim.',100);toast(`${id} simulated commissioning complete.`);}catch(e){commissionLog+='ERROR: '+e.message;toast(e.message,true);}finally{commissionBusy=false;if(view==='installer')renderInstallerSelection();}}
function experiments(){return title('PAIRED SCENARIO COMPARISON','Test the response. Keep the evidence.','Compare fixed and adaptive policies with identical arrival streams and three random seeds.',`<a class="button" href="./study/">Recorded SUMO results ↗</a>`)+`<div class="notice">This built-in experiment is a synthetic queue model, not SUMO or your calibrated study. It includes unfinished vehicles in the stopped-time proxy and models pedestrian requests rather than physical crossings.</div><div class="scenario-grid">${Object.entries(SCENARIOS).map(([k,s],i)=>`<button class="scenario-card ${experimentScenario===k?'active':''}" data-experiment-scenario="${k}"><span class="scenario-number">SCENARIO 0${i+1}</span><strong>${s.name}</strong><p>${s.description}</p></button>`).join('')}</div><div class="row-actions"><button class="button dark" data-action="experiment">Run paired comparison ↗</button><span class="hint">240 s · seeds 11, 42, 93 · same project and demand</span></div><div id="experiment-results" class="subsection">${experiment?experimentResults():`<section class="panel"><div class="empty">Run a comparison to inspect throughput, remaining queues, pedestrian request waits, and conservation checks. Improvement is not assumed.</div></section>`}</div><section class="panel subsection"><div class="panel-head"><h2>Use your real SUMO study</h2><span class="badge blue">ADAPTER INCLUDED</span></div><div class="panel-body"><p class="subtitle">The Python adapter reads lane and signal states from a running SUMO scenario and exports the replay format used by this C2C view. It preserves the provided provenance. Its default mode observes the existing SUMO controller.</p><div class="code subsection">python tools/sumo_adapter.py --sumocfg YOUR_STUDY.sumocfg \
  --mapping YOUR_LANE_MAPPING.json --project YOUR_PROJECT.json \
  --output study-replay.json --duration 300</div><p class="section-note">Supply the actual three TLS IDs, approach-lane groups and exit lanes. The adapter cannot infer approved signal phases or detector locations. SUMO replay health is unreported unless supplied separately.</p><button class="button small" data-action="sample-replay">Download synthetic replay example</button></div></section>`;}
function experimentResults(){const avg=(policy,k)=>{const a=experiment.runs.filter(r=>r.policy===policy);return a.reduce((s,r)=>s+r[k],0)/a.length;},f=avg('fixed','stopped_time_per_arrival_s'),a=avg('adaptive','stopped_time_per_arrival_s'),change=f?(a-f)/f*100:null,max=Math.max(f,a,1),ped=Math.max(...experiment.runs.map(r=>r.max_pedestrian_request_wait_s));return `<div class="split"><section class="panel"><div class="panel-head"><h2>Stopped time per arrival</h2><span class="badge gray">PROXY</span></div><div class="panel-body"><div class="result-big">${change===null?'—':`${change>0?'+':''}${change.toFixed(1)}%`} <span class="hint">adaptive versus fixed</span></div><div class="metric-comparison"><div class="metric-bar"><span>Fixed</span><i style="width:${f/max*100}%"></i><strong>${f.toFixed(1)} s</strong></div><div class="metric-bar adaptive"><span>Adaptive</span><i style="width:${a/max*100}%"></i><strong>${a.toFixed(1)} s</strong></div></div><p class="section-note">Queue area ÷ arrivals, averaged across three paired runs. Includes waiting accumulated by vehicles still queued at the end.</p></div></section><section class="panel"><div class="panel-head"><h2>Checks & traceability</h2></div><div class="panel-body"><dl class="detail-list"><dt>Scenario</dt><dd>${SCENARIOS[experiment.scenario].name}</dd><dt>Matched demand</dt><dd>Identical seeds and arrival streams per pair</dd><dt>Conservation</dt><dd>${experiment.runs.every(r=>r.conservation_error===0)?'All runs balance: arrived = departed + queued':'ERROR — review exported runs'}</dd><dt>Max request wait</dt><dd>${ped.toFixed(0)} s across all runs</dd><dt>Source</dt><dd>Synthetic / not calibrated</dd></dl><div class="row-actions"><button class="button small" data-action="experiment-csv">Download CSV</button><button class="button small" data-action="experiment-json">Download JSON</button></div></div></section></div><section class="panel subsection"><div class="table-wrap"><table><thead><tr><th>SEED</th><th>POLICY</th><th>ARRIVED</th><th>DEPARTED</th><th>QUEUED</th><th>MEAN QUEUE</th><th>STOPPED / ARRIVAL</th><th>MAX PED REQUEST WAIT</th></tr></thead><tbody>${experiment.runs.map(r=>`<tr><td>${r.seed}</td><td>${r.policy}</td><td>${r.arrived}</td><td>${r.departed}</td><td>${r.remaining}</td><td>${r.mean_queue_veh.toFixed(1)}</td><td>${r.stopped_time_per_arrival_s.toFixed(1)} s</td><td>${r.max_pedestrian_request_wait_s} s</td></tr>`).join('')}</tbody></table></div></section>`;}
function navigate(v,{scroll=true,device=false}={}){if(v!=='installer')borderPick=null;if(v==='installer'&&device){installerSiteId=project.devices.find(d=>d.id===selectedD)?.intersection_id||selectedJ;installerDeviceChosen=true;}else if(v==='installer'&&view!=='installer'){installerSiteId=null;installerDeviceChosen=false;installerDrag=false;}view=v;location.hash=v;render();if(scroll)window.scrollTo({top:0,behavior:'smooth'});}
function resetEngine(){engine=new Engine(project,{scenario,seed:42});replay=null;replayIndex=0;lastVisible=engine.snapshot();lastHistory=[];running=false;}
function editSites(){const d=$('#dialog-content');d.innerHTML='<h2>Study sites & map references</h2><p>The default study selection follows paper p.33, with junction details on pp.36–38. Edit these references only when the study changes. Moving a site shifts its proposed lane geometry and devices; inspect every position afterward.</p>'+`<form id="sites-form">${project.intersections.map(j=>`<fieldset style="border:1px solid #dce4d3;border-radius:6px;margin:14px 0;padding:14px"><legend class="mono">${esc(j.id)}</legend><div class="field"><label>Intersection / road crossing name<input name="${esc(j.id)}_name" value="${esc(j.name)}" required maxlength="100"></label></div><div class="two-fields"><div class="field"><label>Latitude<input name="${esc(j.id)}_latitude" type="number" step="any" min="-90" max="90" value="${j.latitude}" required></label></div><div class="field"><label>Longitude<input name="${esc(j.id)}_longitude" type="number" step="any" min="-180" max="180" value="${j.longitude}" required></label></div></div><label class="toggle-label"><input name="${esc(j.id)}_verified" type="checkbox" ${j.location_status==='verified'?'checked':''}>This is a confirmed study intersection (not a surveyed device position)</label></fieldset>`).join('')}<div class="row-actions"><button class="button dark" type="submit">Apply site locations</button><button class="button" type="button" data-action="restore-study">Restore paper study layout</button></div><p class="hint">Restoring loads the supplied paper’s default Mandaue geometry. The current project is backed up and can be restored with Undo last layout change.</p></form>`;$('#dialog').showModal();}
function tour(){ $('#dialog-content').innerHTML='<h2>Walk through the PASADA chain</h2><ol><li><strong>Installation → Area planner:</strong> choose a radius, click a detected junction, customize its lane template, then save or export the plan.</li><li><strong>Emergency fleet:</strong> register each vehicle and assign its beacon. Choose <strong>Install beacon</strong> to prepare its unique configuration with the shared firmware build.</li><li><strong>Installation → Configured sites:</strong> review the paper’s three Mandaue study sites. Align each puck group to the centre of the expected vehicle path, then check cabinet positions.</li><li>Select a device and choose <strong>Install on virtual device</strong>. Inspect the simulated persistence and readback result.</li><li><strong>Export project</strong>, then import that file. C2C uses the same identity and geographic configuration.</li><li>In <strong>Control center</strong>, start a replay, stop a sensor heartbeat, request emergency priority, restore it, and observe fixed fallback and recovery.</li><li>In <strong>Experiments</strong>, compare paired runs and download results. Import an actual SUMO replay when your lane mappings are ready.</li></ol><p>The browser engine and virtual device are explicitly synthetic. No physical signal output, camera feed or radio connection is claimed.</p><button class="button dark" data-action="tour-start">Begin with installation</button>';$('#dialog').showModal();}
function timingDialog(site=selectedJ){const j=project.intersections.find(j=>j.id===site)||project.intersections[0];const labels={min_green_s:'Minimum green (s)',max_green_s:'Maximum green (s)',fixed_green_s:'Fixed-plan green (s)',yellow_s:'Yellow (s)',all_red_s:'All-red (s)',pedestrian_service_s:'Modeled pedestrian service (s)',pedestrian_max_wait_s:'Pedestrian request wait limit (s)',heartbeat_s:'Heartbeat interval (s)',heartbeat_timeout_s:'Heartbeat timeout (s)',recovery_stable_s:'Stable recovery interval (s)',downstream_capacity_veh:'Downstream capacity (vehicles)'};$('#dialog-content').innerHTML=`<h2>Simulation timing profile</h2><div class="notice">These are draft model assumptions. They are not approved field timings or a physical crossing-clearance design.</div><form id="timing-form"><div class="field"><label>Study site<select name="site" id="timing-site">${project.intersections.map(x=>`<option value="${esc(x.id)}" ${x.id===j.id?'selected':''}>${esc(x.id)} / ${esc(x.name)}</option>`).join('')}</select></label></div><div class="field"><label>Local model<select name="model"><option value="pressure-v0" ${j.model==='pressure-v0'?'selected':''}>pressure-v0 · bounded queue-pressure heuristic</option><option value="fixed-v0" ${j.model==='fixed-v0'?'selected':''}>fixed-v0 · fixed timing</option></select></label></div><div class="two-fields">${Object.keys(SETTINGS).map(k=>`<div class="field"><label>${labels[k]}<input name="${k}" value="${j.timing[k]}" type="number" step="1" min="1" max="600" required></label></div>`).join('')}</div><button class="button dark" type="submit">Apply simulation profile</button></form>`;if(!$('#dialog').open)$('#dialog').showModal();}
function coverageTableHTML(){return `<section class="panel coverage-panel"><div class="panel-head"><h2>Required puck coverage</h2><span class="badge">5 / 30 / 60 m + EXIT COUNTERS</span></div><div class="table-wrap"><table><thead><tr><th>SITE</th><th>INCOMING LANES</th><th>UPSTREAM PUCKS</th><th>OUTGOING LANES</th><th>DOWNSTREAM COUNTERS</th></tr></thead><tbody>${project.intersections.map(j=>{const c=detectorCoverage(project,j);return `<tr><td>${esc(j.id)}</td><td>${c.inbound_lanes}</td><td>${c.upstream} · 3 per lane</td><td>${c.outbound_lanes}</td><td>${c.downstream} · 1 per lane</td></tr>`;}).join('')}</tbody></table></div><div class="table-note">Incoming lanes use 5 m, 30 m and 60 m offsets along the lane from its signal reference. Outgoing lanes each have one counter, initially 10 m beyond the exit reference. Lane counts follow map tags and remain subject to verification.</div></section>`;}
function coverageDialog(){$('#dialog-content').innerHTML='<h2>Lane coverage across the study area</h2>'+coverageTableHTML()+'<div class="row-actions subsection"><button class="button" data-action="lane-layout">Edit lane references</button><button class="button" data-action="undo-layout" '+(undoLayout?'':'disabled')+'>Undo last layout change</button></div>';$('#dialog').showModal();}
function radioCapacityHTML(){const issues=radioCapacityIssues(project);return issues.length?`<div class="notice subsection"><strong>Radio topology still needs review.</strong> ${issues.map(x=>`${esc(x.intersection_id)}: ${x.required_peers} planned peers`).join(' · ')}. The current single-group profile allows ${project.communications.encrypted_peer_budget}. All required pucks remain in the installation plan; physical radio provisioning is unresolved.</div>`:'';}
function laneLayoutDialog(id){const d=project.devices.find(d=>d.id===selectedD);const pair=project.intersections.flatMap(j=>j.lanes.filter(l=>l.path).map(l=>({j,l})));if(!pair.length){toast('This imported project has no road-aligned lane paths.',true);return;}const {j,l}=pair.find(x=>x.l.id===(id||d?.lane_id))||pair.find(x=>x.j.id===selectedJ)||pair[0];$('#dialog-content').innerHTML=`<h2>Lane alignment & signal reference</h2><p>Place the puck directly beneath the expected vehicle centre, halfway between the lane edges. The two white dashed lines are the draft lane borders; no continuous centre guide is drawn under the puck. A lateral adjustment shifts the complete row sideways while keeping its 5 / 30 / 60 m chainages. Confirm exact signal / stop-line coordinates on site.</p><form id="lane-layout-form"><div class="field"><label for="layout-lane">Road lane</label><select name="lane" id="layout-lane">${pair.map(x=>`<option value="${esc(x.l.id)}" ${x.l.id===l.id?'selected':''}>${esc(x.j.id)} · ${esc(x.l.road_name)} · ${x.l.flow} lane ${x.l.lane_number}</option>`).join('')}</select></div><div class="two-fields"><div class="field"><label>Signal / exit reference latitude<input name="latitude" type="number" step="any" min="-90" max="90" value="${l.path[0][0]}" required></label></div><div class="field"><label>Signal / exit reference longitude<input name="longitude" type="number" step="any" min="-180" max="180" value="${l.path[0][1]}" required></label></div></div><div class="two-fields"><div class="field"><label>Road bearing away from junction (°)<input name="bearing" type="number" step="any" min="0" max="360" value="${bearingDeg(l.path).toFixed(4)}" required></label></div><div class="field"><label>Site downstream offset (m)<input name="downstream" type="number" step="any" min="1" max="60" value="${j.downstream_offset_m||10}" required></label></div></div><div class="field"><label>Shift lane centre sideways (m)<input name="lateral" type="number" step="0.1" min="-10" max="10" value="0" required><small>Positive = right looking away from the junction; negative = left. Applied once when saved.</small></label></div><p class="hint">${esc(l.reference_status||'Provisional reference')}. The downstream offset applies to every outgoing lane at ${esc(j.id)}. Each incoming lane retains exactly 5 / 30 / 60 m.</p><div class="row-actions"><button type="submit" class="button dark">Save lane alignment</button><button type="button" class="button danger" data-action="remove-lane">Remove this lane</button></div></form>`;if(!$('#dialog').open)$('#dialog').showModal();}
function addLaneDialog(){const rows=project.intersections.flatMap(j=>j.lanes.filter(l=>l.path).map(l=>({j,l})));if(!rows.length){toast('No road lane is available as a template.',true);return;}const device=project.devices.find(d=>d.id===selectedD),candidate=rows.find(x=>x.l.id===device?.lane_id)||rows.find(x=>x.j.id===selectedJ&&x.l.flow==='inbound')||rows[0];const outer=rows.filter(x=>x.j.id===candidate.j.id&&x.l.arm_id===candidate.l.arm_id&&x.l.flow===candidate.l.flow).sort((a,b)=>b.l.lane_number-a.l.lane_number)[0];$('#dialog-content').innerHTML=`<h2>Add a parallel road lane</h2><p>An incoming lane automatically receives all three upstream pucks. An outgoing lane receives exactly one downstream counter.</p><form id="add-lane-form"><div class="field"><label>Existing lane to copy<select id="add-lane-base" name="base">${rows.map(x=>`<option value="${esc(x.l.id)}" ${x.l.id===outer.l.id?'selected':''}>${esc(x.j.id)} · ${esc(x.l.road_name)} · ${x.l.flow} lane ${x.l.lane_number}</option>`).join('')}</select></label></div><div class="field"><label>Parallel shift from that lane (m; right is positive)<input id="lane-delta" name="delta" type="number" step="any" min="-20" max="20" value="${outer.l.flow==='inbound'?-3.2:3.2}" required></label></div><button type="submit" class="button dark">Add lane and required pucks</button></form>`;if(!$('#dialog').open)$('#dialog').showModal();}
function removeSelectedLane(){const laneId=$('#layout-lane')?.value;if(!laneId)return;const p=clone(project),j=p.intersections.find(j=>j.lanes.some(l=>l.id===laneId));j.lanes=j.lanes.filter(l=>l.id!==laneId);p.devices=p.devices.filter(d=>d.lane_id!==laneId);const errors=validateProject(p);if(errors.length)throw Error(errors.join(' '));undoLayout=clone(project);project=p;selectedD=j.controller_device_id;persist();resetEngine();$('#dialog').close();render();toast('Lane and its detector group removed. Undo is available in Lane coverage.');}
function updateBoundaryCounts(){const el=$('#flow-balance');if(!el)return;el.innerHTML=`<div class="table-wrap"><table><thead><tr><th>SITE</th><th>INFLOW · 60 m PUCKS</th><th>OUTFLOW · EXIT COUNTERS</th><th>STORED IN MODEL</th><th>INFLOW − OUTFLOW − STORED</th></tr></thead><tbody>${current().intersections.map(j=>{const c=boundaryTotals(project,j);return `<tr><td>${esc(j.id)}</td><td>${c.reported?c.inflow:'Unreported'}</td><td>${c.reported?c.outflow:'Unreported'}</td><td>${c.reported?c.stored:'—'}</td><td>${c.reported?c.residual:'—'}</td></tr>`;}).join('')}</tbody></table></div><div class="table-note">Only the 60 m boundary detector contributes to inflow; 5 m and 30 m detections are not added again. Each modeled departure increments exactly one outgoing lane counter. These are synthetic passage tallies; real field counts remain unconnected.</div>`;}
async function action(a){try{
 if(a==='vehicle-new'){editVehicle();}
 else if(a==='install-devices-mode'){deviceInstallerSiteId=areaPlanner?.study?.id||areaPlanner?.plan?.id||deviceInstallerState.siteId;installerMode='devices';render();window.scrollTo(0,0);}
 else if(a==='install-area-mode'){installerMode='area';render();}
 else if(a==='install-road-mode'){installerMode='road';render();}
 else if(a==='install-beacon-mode'){installerMode='beacon';render();}
 else if(a==='play'){running=!running;if(replay&&replayIndex>=replay.frames.length-1)replayIndex=0;updateOperations();}
 else if(a==='step'){if(replay)replayIndex=Math.min(replayIndex+10,replay.frames.length-1);else engine.step(10);if(engine.c2cOnline){lastVisible=engine.snapshot();lastHistory=clone(engine.history);}updateOperations();}
 else if(a==='reset'){if(replay){replayIndex=0;running=false;}else resetEngine();updateOperations();}
 else if(a==='fit')fitMap();
 else if(a==='map-geometry')setMapBase('geometry');
 else if(a==='map-imagery')setMapBase('imagery');
 else if(a==='installer-all'){installerSiteId=null;installerDeviceChosen=false;installerDrag=false;borderPick=null;render();}
 else if(a==='installer-fit')fitInstallationSite();
 else if(a==='installer-drag'){installerDrag=!installerDrag;render();}
 else if(a==='identity-notes')identityDialog();
 else if(a==='previous-project'){const old=localStorage.getItem(STORE+'-before-mandaue-p33');if(old)download('PASADA_previous_Colon_layout.json',JSON.parse(old));else toast('No previous generated layout is stored in this browser.',true);}
 else if(a==='border-align'){if(replay)throw Error('Imported replays are read-only. Open an installation project to align lanes.');const d=project.devices.find(d=>d.id===selectedD);if(d?.role!=='sensor')return;const deviceId=d.id;borderPick={deviceId,points:[]};follow=true;navigate('installer',{scroll:false,device:true});map.setView([d.latitude,d.longitude],21,{animate:false});$('#geo-map').scrollIntoView({block:'center'});}
 else if(a==='border-cancel'){borderPick=null;follow=true;render();}
 else if(a==='focus-lane'){const d=project.devices.find(d=>d.id===selectedD),j=project.intersections.find(j=>j.id===d.intersection_id),l=j.lanes.find(l=>l.id===d.lane_id);if(l?.path){map.fitBounds(L.latLngBounds(slicePath(l.path,0,l.flow==='inbound'?60:j.downstream_offset_m)).pad(.25),{maxZoom:20,padding:[35,35]});$('#geo-map').scrollIntoView({block:'center',behavior:'smooth'});}}
 else if(a==='fullscreen'){$('.operations-grid>.panel').classList.toggle('full-map');setTimeout(()=>map.invalidateSize(),50);}
 else if(a==='fault'){engine.setDeviceOnline(selectedD,engine.failed.has(selectedD));updateOperations();}
 else if(a==='emergency'||a==='beacon-start'){if(replay)throw Error('Return to the synthetic workspace to run the beacon demo.');engine.startBeaconDemo(selectedJ);running=true;const site=project.intersections.find(j=>j.id===selectedJ);if(map)map.fitBounds(L.latLngBounds(site.lanes.filter(l=>l.flow==='inbound').flatMap(l=>slicePath(l.path,0,Math.min(110,pathLength(l.path))))).pad(.15),{maxZoom:19,padding:[35,35]});$('#geo-map')?.scrollIntoView({block:'center',behavior:'smooth'});updateOperations();toast('Synthetic 1 Hz beacon stream started. Heading and speed require consecutive fixes.');}
 else if(a==='beacon-pause'){engine.pauseBeaconDemo();updateOperations();}
 else if(a==='beacon-export'){download('PASADA_synthetic_beacon_packets.ndjson',engine.beaconPackets.filter(p=>p.timestamp_s<=current().t).map(p=>JSON.stringify(p)).join('\n'),'application/x-ndjson');}
 else if(a==='pedestrian'){engine.requestPedestrian(selectedJ,'EW');updateOperations();}
 else if(a==='c2c'){if(engine.c2cOnline){lastVisible=engine.snapshot();lastHistory=clone(engine.history);}engine.setC2C(!engine.c2cOnline);updateOperations();}
 else if(a==='edit-selected'){const d=project.devices.find(d=>d.id===selectedD),v=d?.role==='beacon'&&fleetRecords(project).find(v=>v.beacon_id===d.id);if(v)installVehicle(v.id);else{installerMode='road';follow=true;navigate('installer',{device:true});}}
 else if(a==='edit-sites')editSites();
 else if(a==='unlocate-controller'){const d=project.devices.find(x=>x.id===selectedD);if(d?.role==='controller'){undoLayout=clone(project);d.latitude=null;d.longitude=null;d.location_status='unlocated';d.commissioning={state:'planned',transport:'simulated'};persist();resetEngine();render();toast('Cabinet position cleared. Junction and puck geometry are retained.');}}
 else if(a==='restore-study'){undoLayout=clone(project);localStorage.setItem(STORE+'-before-paper-restore',JSON.stringify(project));project=defaultProject();installerSiteId=null;installerDeviceChosen=false;installerDrag=false;selectedJ=project.intersections[0].id;selectedD=project.devices[0].id;persist();resetEngine();experiment=null;$('#dialog').close();render();toast('Paper study layout restored. Previous layout retained; Undo is available in Lane coverage.');}
 else if(a==='timing-profiles')timingDialog();
 else if(a==='commission')await commission();
 else if(a==='device-json')download(`${selectedD}.json`,deviceConfiguration(project,selectedD));
 else if(a==='export-project')download('PASADA_installation.json',project);
 else if(a==='export-events')download('PASADA_events.ndjson',events().map(e=>JSON.stringify(e)).join('\n'),'application/x-ndjson');
 else if(a==='export-replay'){if(!replay&&!engine.frames.length){toast('Run the scenario before exporting its replay.',true);return;}download('PASADA_replay.json',replay||engine.replay());}
 else if(a==='sample-replay'){const e=new Engine(project,{scenario:'resilience'});e.step(180);download('PASADA_synthetic_example.json',e.replay());}
 else if(a==='experiment'){experiment=runExperiment(project,{scenario:experimentScenario});$('#experiment-results').innerHTML=experimentResults();toast('Six paired scenario runs completed.');}
 else if(a==='experiment-csv'&&experiment)download('PASADA_comparison.csv',metricCSV(experiment),'text/csv');
 else if(a==='experiment-json'&&experiment)download('PASADA_comparison.json',experiment);
 else if(a==='tour-start'){$('#dialog').close();installerMode='area';navigate('installer');}
 else if(a==='add-puck')addLaneDialog();
 else if(a==='lane-layout')laneLayoutDialog();
 else if(a==='coverage')coverageDialog();
 else if(a==='remove-lane')removeSelectedLane();
 else if(a==='undo-layout'&&undoLayout){project=undoLayout;undoLayout=null;persist();resetEngine();render();toast('Previous layout restored.');}
 }catch(e){toast(e.message,true);}}
function addPuckDialog(){const el=$('#dialog-content');el.innerHTML=`<h2>Add a planned puck</h2><form id="add-puck-form"><div class="field"><label>Unique device ID<input name="id" value="PUCK-NEW-${project.devices.length+1}" pattern="[A-Za-z0-9_-]{1,64}" required></label></div><div class="two-fields"><div class="field"><label>Intersection<select name="site">${project.intersections.map(j=>`<option>${esc(j.id)}</option>`).join('')}</select></label></div><div class="field"><label>Approach<select name="approach">${DIRECTIONS.map(d=>`<option>${d}</option>`).join('')}</select></label></div></div><div class="two-fields"><div class="field"><label>Placement<select name="placement"><option>upstream</option><option>downstream</option></select></label></div><div class="field"><label>Offset (m)<input name="offset" type="number" value="30" min="0" max="200" required></label></div></div><p class="hint">The puck begins at the site center. Drag it to the correct lane position afterward. Peer capacity is checked before adding.</p><button type="submit" class="button dark">Add puck</button></form>`;$('#dialog').showModal();}
document.addEventListener('click',e=>{const vehicleSelect=e.target.closest('[data-vehicle-select]');if(vehicleSelect){selectedVehicleId=vehicleSelect.dataset.vehicleSelect;refreshFleet();return;}const vehicleEdit=e.target.closest('[data-vehicle-edit]');if(vehicleEdit){editVehicle(vehicleEdit.dataset.vehicleEdit);return;}const vehicleInstall=e.target.closest('[data-vehicle-install]');if(vehicleInstall){installVehicle(vehicleInstall.dataset.vehicleInstall);return;}const vehicleTest=e.target.closest('[data-vehicle-test]');if(vehicleTest){try{if(replay)throw Error('Imported replays are read-only.');const v=fleetRecords(project).find(v=>v.id===vehicleTest.dataset.vehicleTest);if(!v||!beaconAuthorization(project,v.beacon_id,v.id).allowed)throw Error('This vehicle is not approved for priority.');selectedJ=v.home_site_id;selectedD=v.beacon_id;navigate('operations');engine.startBeaconDemo(selectedJ,v.beacon_id);running=true;if(map){const j=project.intersections.find(j=>j.id===selectedJ);map.fitBounds(L.latLngBounds(j.lanes.filter(l=>l.flow==='inbound').flatMap(l=>slicePath(l.path,0,Math.min(110,pathLength(l.path))))).pad(.15),{maxZoom:19,padding:[35,35]});}updateOperations();}catch(err){toast(err.message,true);}return;}const site=e.target.closest('[data-installation-site]');if(site){selectInstallationSite(site.dataset.installationSite);return;}const v=e.target.closest('button[data-view]');if(v){if(v.dataset.view==='installer')installerMode='area';navigate(v.dataset.view);return;}const a=e.target.closest('[data-action]');if(a){action(a.dataset.action);return;}const j=e.target.closest('[data-junction]');if(j){selectedJ=j.dataset.junction;selectedD=project.intersections.find(x=>x.id===selectedJ).controller_device_id;const p=project.intersections.find(x=>x.id===selectedJ);if(map)map.fitBounds(L.latLngBounds([[p.latitude,p.longitude],...project.devices.filter(d=>d.intersection_id===p.id&&hasDevicePosition(d)).map(d=>[d.latitude,d.longitude])]).pad(.12),{maxZoom:19,padding:[25,25]});updateOperations();return;}const cabinet=e.target.closest('[data-controller]');if(cabinet){installerMode='road';selectedD=cabinet.dataset.controller;selectedJ=project.devices.find(x=>x.id===selectedD).intersection_id;follow=true;navigate('installer',{device:true});return;}const d=e.target.closest('[data-device]');if(d){installerDeviceChosen=true;selectedD=d.dataset.device;selectedJ=project.devices.find(x=>x.id===selectedD).intersection_id;if(borderPick){borderPick=null;follow=true;render();}else renderInstallerSelection();return;}const s=e.target.closest('[data-experiment-scenario]');if(s){experimentScenario=s.dataset.experimentScenario;experiment=null;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-device]'))e.target.click();});
document.addEventListener('change',e=>{
 if(e.target.id==='fleet-filter'){fleetFilter=e.target.value;refreshFleet();return;}
 if(e.target.id==='vehicle-authorization'){$('#vehicle-approval-reference').required=e.target.value==='approved';return;}
 if(e.target.id==='beacon-install-vehicle'){selectedVehicleId=e.target.value;commissionLog='';commissionPercent=0;renderInstallerSelection();return;}
 if(e.target.id==='beacon-target'){selectedJ=e.target.value;selectedD=project.intersections.find(j=>j.id===selectedJ).controller_device_id;updateOperations();}
 if(e.target.id==='speed')speed=Number(e.target.value);
 if(e.target.id==='scenario'){scenario=e.target.value;resetEngine();updateOperations();}
 if(e.target.id==='device-id'){installerDeviceChosen=true;selectedD=e.target.value;selectedJ=project.devices.find(d=>d.id===selectedD).intersection_id;if(borderPick){borderPick=null;follow=true;render();}else renderInstallerSelection();}
 if(e.target.id==='device-filter')renderInstallerTable();
 if(e.target.id==='timing-site')timingDialog(e.target.value);
 if(e.target.id==='layout-lane')laneLayoutDialog(e.target.value);
 if(e.target.id==='add-lane-base')$('#lane-delta').value=project.intersections.flatMap(j=>j.lanes).find(l=>l.id===e.target.value)?.flow==='inbound'?-3.2:3.2;
});
document.addEventListener('input',e=>{if(e.target.id==='fleet-search'){fleetQuery=e.target.value;refreshFleet();return;}if(e.target.id==='scrub'){replayIndex=Number(e.target.value);running=false;updateOperations();}});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='vehicle-form')return;e.preventDefault();const form=e.target;try{if(replay)throw Error('Imported replays are read-only.');const input=Object.fromEntries(new FormData(form)),result=saveVehicle(project,input,{id:form.dataset.editId||undefined}),errors=validateProject(result.project);if(errors.length)throw Error(errors[0]);project=result.project;selectedVehicleId=result.vehicle.id;persist();engine.project=clone(project);engine.beaconTracker.project=engine.project;for(const d of project.devices)if(engine.lastSeen[d.id]===undefined)engine.lastSeen[d.id]=engine.t;for(const [siteId,request]of Object.entries(engine.emergencies))if(request.beacon_id&&!beaconAuthorization(project,request.beacon_id).allowed)delete engine.emergencies[siteId];if(engine.beaconDemo&&!beaconAuthorization(project,engine.beaconDemo.beacon_id).allowed)engine.beaconDemo.finished=true;if(engine.c2cOnline)lastVisible=engine.snapshot();$('#dialog').close();render();toast('Vehicle registration saved.');}catch(err){$('#vehicle-form-error').textContent=err.message;}});
document.addEventListener('submit',e=>{const f=e.target;if(!['device-form','project-form','sites-form','add-puck-form','timing-form','lane-layout-form','add-lane-form'].includes(f.getAttribute('id')))return;e.preventDefault();try{const values=new FormData(f),p=clone(project);
 if(f.getAttribute('id')==='timing-form'){const j=p.intersections.find(j=>j.id===values.get('site'));for(const k of Object.keys(SETTINGS))j.timing[k]=Number(values.get(k));j.model=values.get('model');for(const d of p.devices.filter(d=>d.intersection_id===j.id))d.commissioning={state:'planned',transport:'simulated'};}
 if(f.getAttribute('id')==='device-form')movePuckAndLane(p,selectedD,Number(values.get('latitude')),Number(values.get('longitude')));
 if(f.getAttribute('id')==='lane-layout-form'){const laneId=values.get('lane');const j=p.intersections.find(j=>j.lanes.some(l=>l.id===laneId));editLaneReference(p,j.id,laneId,{latitude:Number(values.get('latitude')),longitude:Number(values.get('longitude')),bearing:Number(values.get('bearing')),downstreamOffset:Number(values.get('downstream')),lateralShift:Number(values.get('lateral'))});}
 if(f.getAttribute('id')==='add-lane-form'){const baseId=values.get('base'),j=p.intersections.find(j=>j.lanes.some(l=>l.id===baseId));const lane=addParallelLane(p,j.id,baseId,Number(values.get('delta')));selectedD=p.devices.find(d=>d.lane_id===lane.id).id;installerDeviceChosen=true;}
 if(f.getAttribute('id')==='project-form'){p.project.name=values.get('name');p.communications.esp_now_channel=Number(values.get('channel'));p.communications.encrypted_peer_budget=Number(values.get('peer'));for(const d of p.devices)d.commissioning={state:'planned',transport:'simulated'};}
 if(f.getAttribute('id')==='sites-form'){for(const j of p.intersections){const lat=Number(values.get(j.id+'_latitude')),lon=Number(values.get(j.id+'_longitude')),dy=lat-j.latitude,dx=lon-j.longitude;j.name=values.get(j.id+'_name');j.latitude=lat;j.longitude=lon;j.location_status=values.get(j.id+'_verified')?'verified':'unconfirmed';translateSiteGeometry(j,dy,dx);for(const d of p.devices.filter(d=>d.intersection_id===j.id)){if(!hasDevicePosition(d))continue;d.latitude=Number((d.latitude+dy).toFixed(7));d.longitude=Number((d.longitude+dx).toFixed(7));if(Number.isFinite(d.reference_latitude)){d.reference_latitude+=dy;d.reference_longitude+=dx;}d.location_status='provisional';d.commissioning={state:'planned',transport:'simulated'};}}}
 if(f.getAttribute('id')==='add-puck-form'){const j=p.intersections.find(j=>j.id===values.get('site')),approach=values.get('approach');p.devices.push({id:values.get('id'),role:'sensor',intersection_id:j.id,lane_id:j.lanes.find(l=>l.approach===approach).id,approach,placement:values.get('placement'),offset_m:Number(values.get('offset')),latitude:j.latitude,longitude:j.longitude,location_status:'provisional',firmware:'pasada-sensor-draft-0.1',commissioning:{state:'planned',transport:'simulated'}});selectedD=values.get('id');}
 const errors=validateProject(p);if(errors.length)throw Error(errors.join(' '));undoLayout=clone(project);project=p;persist();resetEngine();experiment=null;$('#dialog').close();render();if(view==='installer')renderInstallerSelection();toast('Configuration saved. Scenario restarted with the updated project.');
 }catch(err){toast(err.message,true);}});
$('#tour').addEventListener('click',tour);$('#close-dialog').addEventListener('click',()=>$('#dialog').close());$('#export-project').addEventListener('click',()=>action('export-project'));$('#import').addEventListener('click',()=>$('#file-input').click());
$('#file-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>25*1024*1024)throw Error('Import limit is 25 MB. Export a shorter replay.');const p=JSON.parse(await file.text());const errors=p.schema==='pasada.replay/0.1.0'?validateReplay(p):validateProject(p);if(errors.length)throw Error(errors.slice(0,5).join(' '));running=false;if(p.schema==='pasada.replay/0.1.0'){replay=p;replayIndex=0;project=clone(p.project);}else{project=ensureFleetRegistry(p);resetEngine();}selectedJ=project.intersections[0].id;selectedD=project.devices[0].id;persist();experiment=null;navigate('operations');toast(replay?`Loaded ${replay.provenance.source.toUpperCase()} replay. Hardware health remains unreported unless present.`:'Project imported. The same installation now drives C2C.');}catch(err){toast('Import rejected: '+err.message,true);}finally{e.target.value='';}});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(VIEWS.includes(h)&&view!==h){if(h==='installer'){installerSiteId=null;installerDeviceChosen=false;}else borderPick=null;view=h;render();}});
setInterval(()=>{if(!running)return;if(replay){replayIndex=Math.min(replayIndex+speed,replay.frames.length-1);if(replayIndex===replay.frames.length-1)running=false;}else{engine.step(speed);if(engine.c2cOnline){lastVisible=engine.snapshot();lastHistory=clone(engine.history);}}if(view==='operations')updateOperations();else if(view==='vehicles')refreshFleet();},1000);
render();if(view==='installer')renderInstallerSelection();
